## Why This Is Asked

Tests understanding of stability and permutation-based sorting, ensuring candidates can separate data from its keys and reason about time/space trade-offs.

## Key Concepts

- Stable sort
- Permutations
- Time/space complexity
- Merge-based sorting on indices

## Code Example

```javascript
function stableSortIndicesByValue(A){
  const idx = Array.from({length: A.length}, (_, i) => i);
  function merge(left, right){
    const res = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length){
      if (A[left[i]] <= A[right[j]]) res.push(left[i++]);
      else res.push(right[j++]);
    }
    while (i < left.length) res.push(left[i++]);
    while (j < right.length) res.push(right[j++]);
    return res;
  }
  function sort(arr){
    if (arr.length <= 1) return arr;
    const m = Math.floor(arr.length / 2);
    const L = sort(arr.slice(0, m));
    const R = sort(arr.slice(m));
    return merge(L, R);
  }
  const P = sort(idx);
  return { P, sorted: P.map(i => A[i]) };
}
```

## Why This Is Asked
This problem validates DP mastery (two implementations) and handling of substring lookups with a dictionary. It stresses practical constraints and edge-case handling.

## Key Concepts
- Bottom-up DP, Memoization, Time: O(N * maxLen)
- Hash-map lookups for dictionary scores
- Edge cases: no decomposition, empty input, overlapping choices

## Code Example
```javascript
// Bottom-up
function maxScore(s, dict) {
  const maxLen = Math.max(...Object.keys(dict).map(k => k.length));
  const n = s.length;
  const NEG = -1e15;
  const dp = new Array(n + 1).fill(NEG);
  dp[0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let len = 1; len <= Math.min(i, maxLen); len++) {
      const substr = s.slice(i - len, i);
      if (dict.hasOwnProperty(substr) && dp[i - len] !== NEG) {
        dp[i] = Math.max(dp[i], dp[i - len] + dict[substr]);
      }
    }
  }
  return dp[n] === NEG ? -1 : dp[n];
}

// Top-down
function maxScoreTopDown(s, dict) {
  const maxLen = Math.max(...Object.keys(dict).map(k => k.length));
  const memo = new Map();
  function solve(i) {
    if (i === s.length) return 0;
    if (memo.has(i)) return memo.get(i);
    let best = -Infinity;
    for (let len = 1; len <= Math.min(maxLen, s.length - i); len++) {
      const substr = s.substring(i, i + len);
      if (dict.hasOwnProperty(substr)) {
        const val = dict[substr] + solve(i + len);
        if (val > best) best = val;
      }
    }
    memo.set(i, best);
    return best;
  }
  const res = solve(0);
  return res === -Infinity ? -1 : res;
}
``` 

